.annotation-badge {
  display: inline-flex;
  align-items: center;
  border: 1px solid color-mix(in srgb, currentColor 28%, transparent);
  border-radius: 999px;
  padding: .16rem .48rem;
  line-height: 1.1;
  font-size: .72rem;
  letter-spacing: .015em;
}

.provenance-badge.core {
  font-weight: 800;
  border-width: 2px;
}

