      const article = document.getElementById(`m${index + 1}`);
      const speaker = article?.querySelector(".message-speaker")?.textContent || article?.dataset.speaker || article?.dataset.role || "unknown";
      const role = article?.dataset.role || "unknown";
      const meta = article?.querySelector(".message-meta")?.textContent || `#${index + 1}`;
      const text = article?.querySelector(".message-body")?.textContent || "";
      return `<div class="search-result ${pos === provenanceCursor ? "current" : ""}" data-provenance-pos="${pos}"><div class="result-meta">#${index + 1} · ${escapeHtml(speaker)} · ${escapeHtml(role)} · ${escapeHtml(meta.replace(/^#\d+\s*·\s*/, ""))}</div><div class="snippet">${escapeHtml(searchSnippet(text, query))}</div></div>`;
    }).join("") || `<div class="status-text">No matches for ${escapeHtml(provenanceLabel(mode))}.</div>`;
    results.querySelectorAll("[data-provenance-pos]").forEach(node => node.addEventListener("click", () => {
      provenanceCursor = Number(node.dataset.provenancePos);
      jumpToProvenanceCursor();
    }));
    drawer.classList.add("open");
  }

  function escapeHtml(value) {
    return String(value ?? "").replace(/[&<>"']/g, c => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#39;" })[c]);
  }

  function runProvenanceSearch() {
    const mode = selectedProvenance();
    if (mode === "all") return;
    forceRenderAll();
    clearNativeMarks();
    const query = (document.getElementById("threadSearch")?.value || "").trim().toLowerCase();
    provenanceHits = [];
    document.querySelectorAll("#messages > .message").forEach(article => {
      const index = messageIndex(article);
      if (index == null || article.classList.contains("annotation-hidden")) return;
      const role = article.dataset.role || "unknown";
      const text = article.querySelector(".message-body")?.textContent || "";
      const hit = provenanceMatches(role, mode) && (!query || text.toLowerCase().includes(query));
      article.classList.toggle("provenance-search-hit", hit);
      if (hit) provenanceHits.push(index);
    });
    provenanceCursor = provenanceHits.length ? 0 : -1;
    renderProvenanceTimelineMarks();
    renderProvenanceResults(query, mode);
  }

  function renderProvenanceTimelineMarks() {
    const marks = document.getElementById("timelineMarks");
    const timeline = document.getElementById("timeline");
    if (!marks || !timeline || !provenanceHits.length) {
      if (marks) marks.innerHTML = "";
      return;
    }
    const denom = Math.max(1, Number(timeline.max) || 1);
    marks.innerHTML = provenanceHits.slice(0, 500).map(i => `<span class="timeline-mark provenance-timeline-mark" style="left:${(i / denom) * 100}%"></span>`).join("");
  }

  function jumpToProvenanceCursor() {
    if (!provenanceHits.length || provenanceCursor < 0) return;
    provenanceCursor = (provenanceCursor + provenanceHits.length) % provenanceHits.length;
    const index = provenanceHits[provenanceCursor];
    const timeline = document.getElementById("timeline");
    if (timeline) {
      timeline.value = String(index);
      timeline.dispatchEvent(new Event("change", { bubbles: true }));
    } else document.getElementById(`m${index + 1}`)?.scrollIntoView({ behavior: "smooth", block: "center" });
    renderProvenanceResults((document.getElementById("threadSearch")?.value || "").trim(), selectedProvenance());
  }

  function cycleProvenance(delta) {
    if (!provenanceHits.length) return;
    provenanceCursor += delta;
    jumpToProvenanceCursor();
  }

  function installProvenanceSearchInterceptors() {
    const search = document.getElementById("threadSearch");
    const prev = document.getElementById("searchPrev");
    const next = document.getElementById("searchNext");
    if (!search || search.dataset.provenanceInterceptor === "1") return;
    search.dataset.provenanceInterceptor = "1";

    search.addEventListener("input", event => {
      if (selectedProvenance() === "all") return;
      event.stopImmediatePropagation();
      runProvenanceSearch();
